 private function collections(string $module):array{if($module==='history'){return['records'=>$this->store->history->export()];}$s=$this->snapshot($module)['state'];$out=[];foreach($s as$k=>$v){if(in_array($k,['receipts','usage','commands','pendingIntent','consent','memoryEpoch'],true))continue;if(is_array($v))$out[$k]=array_is_list($v)?$v:((count($v)&&count(array_filter($v,'is_array'))===count($v))?array_map(fn($row,$key)=>$row+['id'=>(string)$key],array_values($v),array_keys($v)):[$v]);else $out['settings'][0][$k]=$v;}if($module==='ramble'){try{$q=$this->store->db->prepare('SELECT id,conversation_id,metadata FROM life_chat_attachment WHERE owner_id=?');$q->execute([$this->store->tenantId]);$out['files']=array_map(fn($r)=>json_decode($r['metadata'],true,64,JSON_THROW_ON_ERROR)+['id'=>$r['id'],'conversationId'=>$r['conversation_id']],$q->fetchAll(PDO::FETCH_ASSOC));}catch(PDOException $e){if($e->getCode()!=='42S02'&&!str_contains($e->getMessage(),'no such table'))throw$e;}}return$out;}
