 public function listing(array $in):array{[$limit,$offset]=self::page($in);$m=$in['module']??'';$c=$in['collection']??'';$rows=$this->rows($m,$c);$items=[];foreach($rows as$i=>$r)if(is_array($r))$items[]=self::summary($r,$i,$m,$c);return['items'=>array_slice($items,$offset,$limit),'total'=>count($items),'nextOffset'=>$offset+$limit<count($items)?$offset+$limit:null,'version'=>$m==='history'?null:$this->snapshot($m)['version']];}
 public function search(array $in):array{[$limit,$offset]=self::page($in);$query=LifeStore::text($in['query']??'',300,true);$items=[];foreach(['planner','ramble','opportunities','applications','history']as$m){if(!empty($in['module'])&&$in['module']!==$m)continue;foreach($this->collections($m)as$c=>$rows){if(!empty($in['collection'])&&$in['collection']!==$c)continue;foreach($rows as$i=>$r){if(!is_array($r))continue;$text=json_encode($r,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$at=mb_stripos($text,$query);if($at!==false)$items[]=self::summary($r,$i,$m,$c)+['excerpt'=>mb_substr($text,max(0,$at-80),260)];}}}return['items'=>array_slice($items,$offset,$limit),'total'=>count($items),'nextOffset'=>$offset+$limit<count($items)?$offset+$limit:null];}
 public function get(array $in):array{$m=$in['module']??'';$c=$in['collection']??'';$id=LifeStore::text($in['id']??'',100,true);$offset=$in['offset']??0;if(!is_int($offset)||$offset<0)throw new LifeError('Use a non-negative character offset.',400);foreach($this->rows($m,$c)as$i=>$r)if(is_array($r)&&self::id($r,$i)===$id){$text=json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);$length=mb_strlen($text);return['module'=>$m,'collection'=>$c,'id'=>$id,'version'=>$m==='history'?null:$this->snapshot($m)['version'],'format'=>'json','content'=>mb_substr($text,$offset,20000),'totalCharacters'=>$length,'nextOffset'=>$offset+20000<$length?$offset+20000:null];}throw new LifeError('Record not found in your account.',404);}
 public function file(array $in):array{require_once __DIR__.'/../life/attachments.php';$kind=$in['kind']??'';$id=LifeApplications::id($in['id']??'');$offset=$in['offset']??0;if(!is_int($offset)||$offset<0)throw new LifeError('Use a non-negative byte offset.',400);$rows=match($kind){'planner'=>$this->rows('planner','attachments'),'application'=>$this->rows('applications','documents'),'chat'=>$this->rows('ramble','files'),default=>throw new LifeError('Choose planner, application or chat.',400)};$record=null;foreach($rows as$r)if(($r['id']??'')===$id)$record=$r;if(!$record)throw new LifeError('File not found in this account.',404);$fileId=$kind==='application'?LifeApplications::id($record['fileId']??''):$id;$root=life_attachment_dir($this->config,$this->store->tenantId);$path=$root.($kind==='application'?'/applications':($kind==='chat'?'/chat':'')).'/'.$fileId;if(!is_file($path))throw new LifeError('Stored file bytes are unavailable. Read any extracted text from its record.',404);$size=filesize($path);if($offset>$size)throw new LifeError('Offset is beyond this file.',400);$bytes=file_get_contents($path,false,null,$offset,48000);return['id'=>$id,'name'=>$record['name']??$id,'mime'=>$record['mime']??'application/octet-stream','encoding'=>'base64','data'=>base64_encode($bytes),'totalBytes'=>$size,'nextOffset'=>$offset+strlen($bytes)<$size?$offset+strlen($bytes):null];}
 public function change(array $in):array{if(!in_array('life.write',explode(' ',$this->grant['scopes']),true))throw new LifeError('This connection is read-only.',403);$m=$in['module']??'';$op=$in['operation']??'';if(!in_array($op,self::OPERATIONS[$m]??[],true))throw new LifeError('This operation is unavailable to connected assistants.',403);$v=$in['version']??null;$args=$in['arguments']??null;$request=$in['requestId']??'';if(!is_int($v)||$v<1||!is_array($args)||(!empty($args)&&array_is_list($args))||!is_string($request)||!preg_match('/^[A-Za-z0-9_-]{8,100}$/D',$request))throw new LifeError('Provide the current module version, arguments object and unique requestId (8–100 characters).',400);LifeStore::text($in['instruction']??'',2000,true);$fingerprint=hash('sha256',json_encode([$m,$op,$args],JSON_THROW_ON_ERROR));$db=$this->store->db;$existing=$db->prepare('SELECT * FROM life_oauth_receipt WHERE grant_id=? AND request_id=?');$existing->execute([$this->grant['id'],$request]);if($r=$existing->fetch(PDO::FETCH_ASSOC)){if(!hash_equals($fingerprint,$r['fingerprint']))throw new LifeError('This requestId already saved a different change.',409);return json_decode($r['result_json'],true);}
